reference_solution:
def minimum_column_increment_operations(grid):
    operations=0
    for column in range(len(grid[0])):
        previous=grid[0][column]
        for row in range(1,len(grid)):
            needed=max(grid[row][column],previous+1)
            operations+=needed-grid[row][column]
            previous=needed
    return operations

